// DistributedApplication represents a distributed application that implements
// the IHost and IAsyncDisposable interfaces.
type DistributedApplication interface {
	handleReference

	// Run runs the distributed application
	//
	// When the Aspire app host is launched via RunAsync there are two possible
	// modes that it is running in: - - Developers extending the Aspire application
	// model should consider the lifetime of IHostedService instances which are
	// added to the dependency injection container. For more information on
	// determining the mode that the app host is running in refer to
	// [DistributedApplicationExecutionContext].
	//
	// Parameters:
	//   - options: Optional parameters; see [RunOptions].
	Run(options ...*RunOptions) error

	// Err returns the first error recorded on this wrapper, or nil if the wrapper
	// resolved successfully and no chained operation has failed.
	Err() error
}

// distributedApplication is the unexported impl of DistributedApplication.
type distributedApplication struct {
	*resourceBuilderBase
}

// newDistributedApplicationFromHandle wraps an existing handle as DistributedApplication.
func newDistributedApplicationFromHandle(h *handle, c *client) DistributedApplication {
	return &distributedApplication{resourceBuilderBase: newResourceBuilderBase(h, c)}
}

// Run runs the distributed application
func (s *distributedApplication) Run(options ...*RunOptions) error {
	if s.err != nil { return s.err }
	ctx := context.Background()
	reqArgs := map[string]any{
		"context": s.handle.ToJSON(),
	}
	if len(options) > 0 {
		merged := &RunOptions{}
		for _, opt := range options {
			if opt != nil { merged = deepUpdate(merged, opt) }
		}
		for k, v := range merged.ToMap() { reqArgs[k] = v }
		if merged.CancellationToken != nil {
			ctx = merged.CancellationToken.Context()
			if id := s.client.registerCancellation(merged.CancellationToken); id != "" {
				reqArgs["cancellationToken"] = id
			}
		}
	}
	_, err := s.client.invokeCapability(ctx, "Aspire.Hosting/run", reqArgs)
	return err
}

